var n=`0134-pkhali`;var t=`world-0134`;var a=`GE`;var r=`western-asia`;var s=4;var l=40;var o={en:`Pkhali`,ua:`Пхалі`};var g={en:`A classic dish from Georgia, featuring spinach, walnut, garlic, pomegranate arils. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: шпинат, волоський горіх, часник, зерна граната. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`spinach`,650,`g`],[`water`,600,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`walnut`,230,`g`],[`garlic`,4,`clove`],[`ground-coriander`,6,`g`],[`ground-fenugreek`,3,`g`],[`apple-cider-vinegar`,25,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:15,i:[[`pomegranate-arils`,100,`g`]]}];var u={slug:n,id:t,country:`GE`,region:r,servings:4,minutes:40,title:o,text:g,steps:d};export{a as country,u as default,t as id,l as minutes,r as region,s as servings,n as slug,d as steps,g as text,o as title};